// Keywords to search across Jira and Confluence
const keywords = [
  "Managed DDM",
  "Yggdrasil",
  "Security",
  "Security Architecture",
  "Animal Cell"
];

// Generate date range for filtering recent items
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const isoDate = sevenDaysAgo.toISOString().split('T')[0];

return keywords.map(keyword => ({
  json: {
    keyword,
    sinceDate: isoDate,
    runId: `run_${Date.now()}`
  }
}));

// Process and normalize Jira search results
const keyword = $('🔑 Prepare Keywords').first().json.keyword;
const rawResults = $input.first().json;

if (!rawResults.issues || rawResults.issues.length === 0) {
  return [{ json: { keyword, source: 'jira', items: [], count: 0 } }];
}

const items = rawResults.issues.map(issue => ({
  id: issue.id,
  key: issue.key,
  type: issue.fields.issuetype?.name || 'Unknown',
  summary: issue.fields.summary,
  description: issue.fields.description
    ? (typeof issue.fields.description === 'string'
        ? issue.fields.description.slice(0, 500)
        : JSON.stringify(issue.fields.description).slice(0, 500))
    : 'No description',
  status: issue.fields.status?.name || 'Unknown',
  priority: issue.fields.priority?.name || 'None',
  assignee: issue.fields.assignee?.displayName || 'Unassigned',
  reporter: issue.fields.reporter?.displayName || 'Unknown',
  labels: issue.fields.labels || [],
  components: (issue.fields.components || []).map(c => c.name),
  created: issue.fields.created,
  updated: issue.fields.updated,
  commentCount: issue.fields.comment?.total || 0,
  url: `${ $env.JIRA_BASE_URL }/browse/${issue.key}`
}));

return [{ json: { keyword, source: 'jira', items, count: items.length } }];

// Process and normalize Confluence search results
const keyword = $('🔑 Prepare Keywords').first().json.keyword;
const rawResults = $input.first().json;

if (!rawResults.results || rawResults.results.length === 0) {
  return [{ json: { keyword, source: 'confluence', items: [], count: 0 } }];
}

// Strip HTML tags from body content
function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 600);
}

const items = rawResults.results.map(page => ({
  id: page.id,
  type: page.type,
  title: page.title,
  space: page.space?.name || 'Unknown Space',
  spaceKey: page.space?.key || '',
  excerpt: stripHtml(page.body?.storage?.value),
  labels: (page.metadata?.labels?.results || []).map(l => l.name),
  ancestors: (page.ancestors || []).map(a => a.title).join(' > '),
  lastModified: page.version?.when,
  modifiedBy: page.version?.by?.displayName || 'Unknown',
  url: `${ $env.CONFLUENCE_BASE_URL }${page._links?.webui || '/wiki/spaces/' + page.space?.key}`
}));

return [{ json: { keyword, source: 'confluence', items, count: items.length } }];

// Aggregate all keyword results into a unified intelligence report structure
const allData = $input.all();

// Group by keyword
const byKeyword = {};

for (const item of allData) {
  const { keyword, source, items, count } = item.json;

  if (!byKeyword[keyword]) {
    byKeyword[keyword] = {
      keyword,
      jira: { items: [], count: 0 },
      confluence: { items: [], count: 0 },
      totalCount: 0
    };
  }

  if (source === 'jira') {
    byKeyword[keyword].jira = { items, count };
  } else if (source === 'confluence') {
    byKeyword[keyword].confluence = { items, count };
  }

  byKeyword[keyword].totalCount =
    byKeyword[keyword].jira.count + byKeyword[keyword].confluence.count;
}

// Build summary stats
const summary = {
  generatedAt: new Date().toISOString(),
  keywords: Object.keys(byKeyword),
  totalJiraIssues: Object.values(byKeyword).reduce((sum, k) => sum + k.jira.count, 0),
  totalConfluencePages: Object.values(byKeyword).reduce((sum, k) => sum + k.confluence.count, 0),
  keywordBreakdown: byKeyword
};

return [{ json: summary }];

// Call Claude AI to generate intelligent summaries per keyword
const data = $input.first().json;
const keywordBreakdown = data.keywordBreakdown;

// Build a rich prompt for Claude
function buildPrompt(keyword, keywordData) {
  const jiraItems = keywordData.jira.items.slice(0, 10);
  const confItems = keywordData.confluence.items.slice(0, 10);

  let prompt = `You are a technical program manager at DeLaval, a precision dairy farming company.\n\n`;
  prompt += `Analyze the following Jira and Confluence data for the topic "${keyword}" and produce:\n`;
  prompt += `1. An executive summary (3-4 sentences)\n`;
  prompt += `2. Key themes and findings (bullet points)\n`;
  prompt += `3. Active work items and their status\n`;
  prompt += `4. Recommended next actions\n`;
  prompt += `5. Suggested meeting agenda (if applicable)\n\n`;

  if (jiraItems.length > 0) {
    prompt += `--- JIRA ISSUES (${keywordData.jira.count} total) ---\n`;
    jiraItems.forEach(issue => {
      prompt += `\n[${issue.key}] ${issue.summary}\n`;
      prompt += `  Status: ${issue.status} | Priority: ${issue.priority} | Assignee: ${issue.assignee}\n`;
      prompt += `  Type: ${issue.type} | Components: ${issue.components.join(', ') || 'None'}\n`;
      if (issue.description && issue.description !== 'No description') {
        prompt += `  Description: ${issue.description.slice(0, 200)}...\n`;
      }
    });
  }

  if (confItems.length > 0) {
    prompt += `\n--- CONFLUENCE PAGES (${keywordData.confluence.count} total) ---\n`;
    confItems.forEach(page => {
      prompt += `\n[${page.space}] ${page.title}\n`;
      prompt += `  Path: ${page.ancestors || 'Root'}\n`;
      prompt += `  Last modified by: ${page.modifiedBy}\n`;
      if (page.excerpt) {
        prompt += `  Excerpt: ${page.excerpt.slice(0, 200)}...\n`;
      }
    });
  }

  return prompt;
}

// We'll return one item per keyword for parallel Claude calls
const items = [];
for (const [keyword, keywordData] of Object.entries(keywordBreakdown)) {
  if (keywordData.totalCount > 0) {
    items.push({
      json: {
        keyword,
        keywordData,
        prompt: buildPrompt(keyword, keywordData),
        generatedAt: data.generatedAt,
        totalSummary: {
          keywords: data.keywords,
          totalJiraIssues: data.totalJiraIssues,
          totalConfluencePages: data.totalConfluencePages
        }
      }
    });
  }
}

// If nothing found for any keyword, still produce an empty report item
if (items.length === 0) {
  items.push({
    json: {
      keyword: 'ALL',
      keywordData: null,
      prompt: 'No results found for any of the configured keywords in the past 7 days.',
      generatedAt: data.generatedAt,
      totalSummary: {
        keywords: data.keywords,
        totalJiraIssues: 0,
        totalConfluencePages: 0
      },
      isEmpty: true
    }
  });
}

return items;

// Extract Claude's response and pair with keyword metadata
const claudeResponse = $input.first().json;
const prevNode = $('💬 Prepare Claude AI Prompts').first().json;

const aiText = claudeResponse.content?.[0]?.text || 'Unable to generate summary.';

return [{
  json: {
    keyword: prevNode.keyword,
    aiSummary: aiText,
    keywordData: prevNode.keywordData,
    generatedAt: prevNode.generatedAt,
    totalSummary: prevNode.totalSummary,
    isEmpty: prevNode.isEmpty || false
  }
}];

// Collect all keyword summaries and combine into final report payload
const allSummaries = $input.all();

const reportSections = allSummaries.map(item => item.json);
const firstItem = reportSections[0];

// Build the master report object
const report = {
  title: `DeLaval Intelligence Report — ${new Date(firstItem.generatedAt).toLocaleDateString('sv-SE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}`,
  generatedAt: firstItem.generatedAt,
  totalSummary: firstItem.totalSummary,
  sections: reportSections,
  meetingNotes: generateMeetingNotes(reportSections),
  htmlReport: generateHTMLReport(reportSections, firstItem)
};

function generateMeetingNotes(sections) {
  let notes = `# DeLaval Weekly Intelligence Meeting Notes\n`;
  notes += `**Date:** ${new Date().toLocaleDateString('sv-SE')}\n`;
  notes += `**Generated by:** n8n Automation + Claude AI\n\n`;
  notes += `---\n\n`;

  for (const section of sections) {
    if (section.isEmpty) continue;
    notes += `## ${section.keyword}\n\n`;
    notes += `**Jira Issues:** ${section.keywordData?.jira?.count || 0} | `;
    notes += `**Confluence Pages:** ${section.keywordData?.confluence?.count || 0}\n\n`;
    notes += section.aiSummary + '\n\n';
    notes += `---\n\n`;
  }

  return notes;
}

function generateHTMLReport(sections, meta) {
  const date = new Date(meta.generatedAt).toLocaleDateString('sv-SE');
  let html = `<!DOCTYPE html><html lang="en"><head>`;
  html += `<meta charset="UTF-8"><title>DeLaval Intelligence Report ${date}</title>`;
  html += `<style>`;
  html += `body { font-family: 'Segoe UI', Arial, sans-serif; max-width: 1100px; margin: 0 auto; padding: 32px; background: #f7f9fc; color: #1a202c; }`;
  html += `.header { background: linear-gradient(135deg, #003366, #005499); color: white; padding: 32px 40px; border-radius: 12px; margin-bottom: 32px; }`;
  html += `.header h1 { margin: 0 0 8px 0; font-size: 26px; }`;
  html += `.header p { margin: 0; opacity: 0.85; font-size: 14px; }`;
  html += `.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 32px; }`;
  html += `.stat-card { background: white; border-radius: 10px; padding: 20px; text-align: center; box-shadow: 0 1px 4px rgba(0,0,0,0.08); border-top: 4px solid #005499; }`;
  html += `.stat-card .number { font-size: 36px; font-weight: 700; color: #005499; }`;
  html += `.stat-card .label { font-size: 13px; color: #64748b; margin-top: 4px; }`;
  html += `.section { background: white; border-radius: 10px; padding: 28px 32px; margin-bottom: 24px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); }`;
  html += `.section h2 { color: #003366; border-bottom: 2px solid #e2e8f0; padding-bottom: 12px; margin-top: 0; }`;
  html += `.badge { display: inline-block; background: #e8f0fe; color: #1967d2; border-radius: 20px; padding: 3px 12px; font-size: 12px; font-weight: 600; margin-right: 8px; }`;
  html += `.badge.green { background: #e6f4ea; color: #1e7e34; }`;
  html += `.ai-content { background: #f8fafc; border-left: 4px solid #005499; padding: 16px 20px; border-radius: 0 8px 8px 0; margin-top: 16px; white-space: pre-wrap; font-size: 14px; line-height: 1.7; }`;
  html += `.footer { text-align: center; color: #94a3b8; font-size: 12px; margin-top: 40px; padding-top: 20px; border-top: 1px solid #e2e8f0; }`;
  html += `</style></head><body>`;

  html += `<div class="header"><h1>🐄 DeLaval Intelligence Report</h1><p>Generated on ${date} &bull; Keywords: ${meta.totalSummary.keywords.join(', ')}</p></div>`;

  html += `<div class="stats">`;
  html += `<div class="stat-card"><div class="number">${meta.totalSummary.keywords.length}</div><div class="label">Keywords Tracked</div></div>`;
  html += `<div class="stat-card"><div class="number">${meta.totalSummary.totalJiraIssues}</div><div class="label">Jira Issues Found</div></div>`;
  html += `<div class="stat-card"><div class="number">${meta.totalSummary.totalConfluencePages}</div><div class="label">Confluence Pages Found</div></div>`;
  html += `</div>`;

  for (const section of sections) {
    if (section.isEmpty) continue;
    const jiraCount = section.keywordData?.jira?.count || 0;
    const confCount = section.keywordData?.confluence?.count || 0;
    html += `<div class="section">`;
    html += `<h2>🔖 ${section.keyword}</h2>`;
    html += `<span class="badge">${jiraCount} Jira Issues</span>`;
    html += `<span class="badge green">${confCount} Confluence Pages</span>`;
    html += `<div class="ai-content">${section.aiSummary}</div>`;

    // Show top Jira items
    if (jiraCount > 0) {
      html += `<details style="margin-top:16px"><summary style="cursor:pointer;font-weight:600;color:#005499">View Jira Issues (${jiraCount})</summary><table style="width:100%;border-collapse:collapse;margin-top:12px;font-size:13px">`;
      html += `<tr style="background:#f1f5f9"><th style="padding:8px;text-align:left">Key</th><th style="padding:8px;text-align:left">Summary</th><th style="padding:8px;text-align:left">Status</th><th style="padding:8px;text-align:left">Assignee</th></tr>`;
      section.keywordData.jira.items.slice(0, 8).forEach(issue => {
        html += `<tr style="border-top:1px solid #e2e8f0"><td style="padding:8px"><a href="${issue.url}" target="_blank">${issue.key}</a></td>`;
        html += `<td style="padding:8px">${issue.summary}</td>`;
        html += `<td style="padding:8px">${issue.status}</td>`;
        html += `<td style="padding:8px">${issue.assignee}</td></tr>`;
      });
      html += `</table></details>`;
    }

    // Show top Confluence pages
    if (confCount > 0) {
      html += `<details style="margin-top:12px"><summary style="cursor:pointer;font-weight:600;color:#1e7e34">View Confluence Pages (${confCount})</summary><ul style="margin-top:12px;font-size:13px">`;
      section.keywordData.confluence.items.slice(0, 8).forEach(page => {
        html += `<li style="margin-bottom:6px"><a href="${page.url}" target="_blank">${page.title}</a> <em style="color:#64748b">(${page.space})</em></li>`;
      });
      html += `</ul></details>`;
    }

    html += `</div>`;
  }

  html += `<div class="footer">Generated automatically by n8n + Claude AI &bull; DeLaval Internal Intelligence System</div>`;
  html += `</body></html>`;

  return html;
}

return [{ json: report }];

// Error handler — log failures gracefully
const error = $input.first();
console.error('Workflow error:', JSON.stringify(error.json));

return [{
  json: {
    error: true,
    message: error.json?.message || 'Unknown error occurred',
    timestamp: new Date().toISOString(),
    node: error.json?.node || 'Unknown node'
  }
}];
